<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { api, problem, validation } from '../api'
import type { ApiProblem, CaseDetail } from '../types'
import { categoryNames, metricNames, number, pretty, sourceNames, stateNames } from '../workbench'
import AsyncState from './AsyncState.vue'
import ProblemBox from './ProblemBox.vue'
import VersionPanel from './VersionPanel.vue'
const props = defineProps<{ caseId: string; scoreSetId?: string }>()
const emit = defineEmits<{ scoreChange: [scoreSet: string]; saved: [] }>()
const detail = ref<CaseDetail | null>(null), loading = ref(true), error = ref<ApiProblem | null>(null), formError = ref<ApiProblem | null>(null), saving = ref(false), tags = ref(''), note = ref(''), notice = ref('')
const execution = computed(() => (detail.value?.case.raw_agent?.normalized_execution || {}) as Record<string, unknown>)
const source = computed(() => String(execution.value.source_type || '尚无执行来源'))
let generation = 0
async function load() { const current = ++generation; loading.value = true; error.value = null; detail.value = null; notice.value = ''; try { const data = await api.detail(props.caseId, props.scoreSetId); if (current !== generation) return; detail.value = data; tags.value = data.annotation.manual_tags.join('、'); note.value = data.annotation.note } catch (e) { if (current === generation) error.value = problem(e) } finally { if (current === generation) loading.value = false } }
async function save() { if (!detail.value) return; const items = tags.value.split(/[、,，\n]/).map(x => x.trim()).filter(Boolean); formError.value = validation([...(items.length > 30 ? [{ field: 'manual_tags', message: '最多 30 个原因' }] : []), ...(new Set(items).size !== items.length ? [{ field: 'manual_tags', message: '原因不能重复' }] : []), ...(items.some(x => x.length > 200) ? [{ field: 'manual_tags', message: '每个原因最多 200 字' }] : []), ...(note.value.length > 20000 ? [{ field: 'note', message: '备注最多 20000 字' }] : [])]); if (formError.value) return; saving.value = true; notice.value = ''; try { detail.value.annotation = await api.saveAnnotation(props.caseId, detail.value.score_set.id, { manual_tags: items, note: note.value }); notice.value = '人工原因与备注已保存，原评分和 Judge 理由保留。'; emit('saved') } catch (e) { formError.value = problem(e) } finally { saving.value = false } }
watch(() => [props.caseId, props.scoreSetId], load, { immediate: true })
</script>
<template><section class="panel section-gap"><div class="panel-heading"><h2>冻结用例详情</h2><ElButton size="small" @click="load">刷新详情</ElButton></div><AsyncState :loading="loading" :error="error" @retry="load"><div v-if="detail" class="panel-body"><div class="detail-title"><div><h2 class="mono">{{ detail.case.case_key }}</h2><p class="small muted">Run {{ detail.case.run_id }} · Case {{ detail.case.id }}</p></div><label class="compact-label">评分集<select :value="detail.score_set.id" @change="emit('scoreChange', ($event.target as HTMLSelectElement).value)"><option v-for="item in detail.score_sets" :key="item.id" :value="item.id">{{ item.kind }} · {{ item.status }} · {{ item.id.slice(0, 8) }}</option></select></label></div><div class="evidence-ribbon"><span>{{ sourceNames[source] || source }} · {{ execution.model_execution_verified ? '实际模型已核验' : '实际模型未核验' }}</span><span>{{ detail.case.agent_status === 'FAILED' ? '执行失败' : stateNames[detail.case.agent_status || 'PENDING'] || detail.case.agent_status }}</span><span>阶段 {{ detail.case.phase }}</span><span>质量：{{ stateNames[detail.scoring.evaluation?.conclusion || 'UNDETERMINED'] }}</span><span>Judge：{{ detail.scoring.evaluation?.status || '未完成' }}</span></div><div class="tag-list"><ElTag v-for="tag in detail.automatic_tags" :key="tag" size="small" type="danger">{{ categoryNames[tag] || tag }}</ElTag><ElTag v-for="issue in detail.evaluation_issues" :key="issue" size="small" type="warning">评测异常：{{ issue }}</ElTag></div><div class="detail-reading-grid"><section><h3>原问题</h3><p class="preserve-text">{{ detail.case.case_snapshot.question }}</p><h3>冻结参考行为</h3><p class="preserve-text reference-text">{{ detail.case.case_snapshot.expected_answer }}</p><details class="raw-detail"><summary>预期工具、必评集合与前置条件</summary><pre>{{ pretty(detail.case.case_snapshot) }}</pre></details></section><section><h3>Agent 实际回答</h3><p class="preserve-text answer-text">{{ detail.case.answer === null ? '尚未取得回答' : detail.case.answer || '回答为空字符串' }}</p><dl class="fact-list"><dt>Trace</dt><dd class="mono">{{ detail.case.trace_id || '不可用' }}</dd><dt>计时</dt><dd class="mono small">{{ pretty(detail.case.timing) }}</dd><dt>错误</dt><dd class="mono small">{{ pretty(detail.case.error) }}</dd></dl></section></div><section class="section-gap"><div class="section-title"><h3>按序工具轨迹</h3><span class="small muted">{{ detail.case.observations?.tools_completeness || 'UNAVAILABLE' }}</span></div><p v-if="!detail.traces.length" class="muted small">{{ detail.case.observations?.tools_completeness === 'COMPLETE' ? '完整观测记录证明没有工具调用。' : '轨迹未知或尚未保存，不能据此认定没有调用。' }}</p><ol v-else class="trace-timeline"><li v-for="event in detail.traces" :key="event.event_id"><div class="trace-sequence">{{ event.sequence }}</div><div class="trace-content"><h3>{{ event.name }} <ElTag size="small" type="info">{{ event.source }}</ElTag></h3><p class="small muted">{{ event.status }} · {{ number(event.duration_ms) }} ms · {{ event.completeness }}</p><details class="raw-detail"><summary>实际工具结果</summary><pre>{{ pretty(event.payload ?? event.result) }}</pre></details></div></li></ol></section><section class="section-gap"><h3>检索证据与模型用量</h3><p class="small muted">上下文范围 {{ detail.case.observations?.context_scope || 'UNAVAILABLE' }} · 完整性 {{ detail.case.observations?.context_completeness || 'UNAVAILABLE' }}。引用子集不能视为完整模型上下文。</p><details class="raw-detail"><summary>查看实际观测与证据正文</summary><pre>{{ pretty(detail.case.observations) }}</pre></details><details class="raw-detail"><summary>Agent 用量与逐次尝试</summary><pre>{{ pretty(detail.case.usage) }}</pre></details></section><section class="section-gap"><h3>规则与 Judge 指标</h3><div class="table-scroll"><table><thead><tr><th>指标 / 必评</th><th>判定</th><th>分数</th><th>理由与依据</th></tr></thead><tbody><tr v-for="metric in detail.scoring.metrics" :key="metric.metric"><td>{{ metricNames[metric.metric] || metric.metric }}<p class="table-subtext">{{ metric.required ? '必评' : '可选' }}</p></td><td><ElTag size="small" :type="metric.status === 'FAIL' || metric.status === 'ERROR' ? 'danger' : metric.status === 'PASS' ? 'success' : 'info'">{{ metric.status }}</ElTag></td><td>{{ number(metric.score) }}</td><td><p class="preserve-text">{{ metric.reason }}</p><details class="inline-detail"><summary>判定依据</summary><pre>{{ pretty(metric.evidence) }}</pre></details></td></tr></tbody></table></div><p v-if="!detail.scoring.metrics.length" class="muted small">该评分集尚无已保存指标。</p><div v-for="attempt in detail.scoring.judge_attempts" :key="attempt.attempt" class="judge-attempt"><h3>Judge 尝试 {{ attempt.attempt }} · {{ attempt.status }} <small>{{ number(attempt.duration_ms) }} ms</small></h3><details class="raw-detail"><summary>原始响应与解析理由</summary><pre>{{ pretty(attempt.response) }}</pre></details><details class="raw-detail"><summary>输入、用量与错误</summary><pre>{{ pretty({ request: attempt.request, usage: attempt.usage, error: attempt.error }) }}</pre></details></div><p v-if="!detail.scoring.judge_attempts.length" class="muted small">该评分集尚无模型尝试记录；没有调用不能视为评分成功。</p></section><VersionPanel :value="detail.version_verification" /><section class="section-gap annotation-editor"><h3>人工原因与备注</h3><p class="field-help">只写入当前评分集。人工复核与自动分类、Judge 原理由各自保留。</p><div v-if="notice" class="notice" role="status">{{ notice }}</div><ProblemBox :error="formError" /><label>人工原因（用顿号分隔）<input v-model="tags" placeholder="例如：知识缺失、参考行为需复核" /></label><label>人工备注<textarea v-model="note" rows="4" maxlength="20000" /></label><ElButton type="primary" :loading="saving" @click="save">保存人工标记</ElButton><small class="muted">评分集 {{ detail.score_set.id }} · {{ detail.annotation.updated_at || '尚未保存人工标记' }}</small></section><details class="raw-detail section-gap"><summary>脱敏原始 Agent 记录与来源证明</summary><pre>{{ pretty(detail.case.raw_agent) }}</pre></details></div></AsyncState></section></template>
